import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.Cz0TtJv6.js";const p=JSON.parse('{"title":"CLI reference","description":"Every npm script that matters — scan, vet, run, status, halt, pause, release, force-close, dash, simulate-zap — what each prints and when to use it.","frontmatter":{"title":"CLI reference","description":"Every npm script that matters — scan, vet, run, status, halt, pause, release, force-close, dash, simulate-zap — what each prints and when to use it."},"headers":[],"relativePath":"cli.md","filePath":"cli.md","lastUpdated":1786714422000}'),r={name:"cli.md"};function s(d,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>All commands run from the repo root. Arguments after the script name need the <code>--</code> separator (<code>npm run vet -- &lt;mint&gt;</code>).</p><h2 id="trading-loop" tabindex="-1">Trading loop <a class="header-anchor" href="#trading-loop" aria-label="Permalink to &quot;Trading loop&quot;">​</a></h2><h3 id="npm-run-run" tabindex="-1"><code>npm run run</code> <a class="header-anchor" href="#npm-run-run" aria-label="Permalink to &quot;`npm run run`&quot;">​</a></h3><p>Starts the bot: the tick loop that scans, vets, enters, manages, and exits. Holds the single-instance lock (<code>data/farmer.lock</code>).</p><ul><li><strong>One instance per wallet/DB — ever.</strong> See <a href="./risk#one-instance-per-wallet">Risk &amp; sizing</a>, including the Windows gotcha where killing <code>npm</code> leaves the <code>tsx</code> child trading.</li><li>On a server, prefer PM2 (<code>meteora-farmer</code> app) so crashes auto-restart — see <a href="./advanced">Advanced setup</a>.</li><li>Restart-safe: on boot it reconciles the DB against the chain (chain wins) and resumes.</li></ul><h3 id="npm-run-status" tabindex="-1"><code>npm run status</code> <a class="header-anchor" href="#npm-run-status" aria-label="Permalink to &quot;`npm run status`&quot;">​</a></h3><p>The at-a-glance report, safe to run any time (read-only):</p><ul><li>Open positions table: id, symbol, entry SOL/price, state, claimed fees, opened time.</li><li>Closed totals: count, <strong>measured</strong> realized PnL in SOL, and how much of that was fee income.</li><li>The <strong>paper→live promotion scoreboard</strong>: consecutive profitable days vs the required 7, per-day realized and unrealized-delta lines, and <code>ELIGIBLE</code> when the gate is met.</li></ul><h2 id="stopping-things" tabindex="-1">Stopping things <a class="header-anchor" href="#stopping-things" aria-label="Permalink to &quot;Stopping things&quot;">​</a></h2><h3 id="npm-run-halt" tabindex="-1"><code>npm run halt</code> <a class="header-anchor" href="#npm-run-halt" aria-label="Permalink to &quot;`npm run halt`&quot;">​</a></h3><p>Toggles the <code>HALT</code> file. First run: the farmer closes <strong>all</strong> positions, swaps to SOL, and idles. Second run: clears HALT so the farmer resumes on the next tick. Same file the dashboard&#39;s red HALT button writes.</p><h3 id="npm-run-pause" tabindex="-1"><code>npm run pause</code> <a class="header-anchor" href="#npm-run-pause" aria-label="Permalink to &quot;`npm run pause`&quot;">​</a></h3><p>Toggles the <code>PAUSE</code> file — the soft pause. Trading engine OFF, <strong>positions stay open</strong> and watched; run again to turn back ON. Same file as the dashboard header ON/OFF toggle. Use this for &quot;stop making new decisions&quot;; use <code>halt</code> for &quot;get me out of everything&quot;.</p><h3 id="npm-run-force-close-id-reason" tabindex="-1"><code>npm run force-close -- &lt;id&gt; &quot;&lt;reason&gt;&quot;</code> <a class="header-anchor" href="#npm-run-force-close-id-reason" aria-label="Permalink to &quot;`npm run force-close -- &lt;id&gt; &quot;&lt;reason&gt;&quot;`&quot;">​</a></h3><p>Recovery tool for a DB row stuck <code>open</code> with <strong>nothing behind it on chain</strong> (the manager refuses to guess about such rows on its own). In live mode it checks the chain first and <strong>refuses</strong> if any tracked position account still exists — it cannot be used to write off a real position. The row&#39;s exit values are left NULL on purpose: the outcome is unknown, so it contributes 0 to realized PnL rather than a fabricated number. The command prints the exact undo SQL.</p><h3 id="npm-run-release-sol-note" tabindex="-1"><code>npm run release [-- &lt;sol&gt; [note]]</code> <a class="header-anchor" href="#npm-run-release-sol-note" aria-label="Permalink to &quot;`npm run release [-- &lt;sol&gt; [note]]`&quot;">​</a></h3><p>Returns <strong>banked</strong> SOL (skimmed by profit locks / the retired house-money rule) to the deployable bankroll, through the ledger with a note — not a hand-written DB poke. No argument (or <code>all</code>) releases everything banked; a number releases that much. Prints the before/after banked totals and the undo statement.</p><h2 id="research-diagnosis" tabindex="-1">Research &amp; diagnosis <a class="header-anchor" href="#research-diagnosis" aria-label="Permalink to &quot;Research &amp; diagnosis&quot;">​</a></h2><h3 id="npm-run-scan" tabindex="-1"><code>npm run scan</code> <a class="header-anchor" href="#npm-run-scan" aria-label="Permalink to &quot;`npm run scan`&quot;">​</a></h3><p>One scanner sweep, printed: how many pools were swept, the top candidates with score / fee-TVL / TVL / 30m volume / bin step / base fee / pool address — and when nothing passes (normal in quiet markets), the <strong>closest rejects</strong> with exactly which gate failed and by how much. The fastest way to sanity-check gate settings.</p><h3 id="npm-run-vet-mint" tabindex="-1"><code>npm run vet -- &lt;mint&gt;</code> <a class="header-anchor" href="#npm-run-vet-mint" aria-label="Permalink to &quot;`npm run vet -- &lt;mint&gt;`&quot;">​</a></h3><p>Runs the full vetting engine on a single token and prints the verdict, soft score /100, each hard failure with its value vs limit, and the raw facts JSON (authorities, holders, clusters, RugCheck, age). Use it to answer &quot;why won&#39;t the bot touch this token?&quot;</p><h3 id="npm-run-simulate-zap" tabindex="-1"><code>npm run simulate-zap</code> <a class="header-anchor" href="#npm-run-simulate-zap" aria-label="Permalink to &quot;`npm run simulate-zap`&quot;">​</a></h3><p>Dry-runs the live exit-swap path — Jupiter V6 quote → build transaction → RPC <strong>simulate</strong> — without moving funds. Requires <code>JUPITER_API_KEY</code> and <code>RPC_URL</code> in <code>.env</code>. Optional <code>--mint &lt;token_mint&gt; --amount-raw &lt;n&gt;</code> targets a specific token. Run this before trusting live mode with the zap path.</p><h3 id="npm-run-heartbeat-check" tabindex="-1"><code>npm run heartbeat-check</code> <a class="header-anchor" href="#npm-run-heartbeat-check" aria-label="Permalink to &quot;`npm run heartbeat-check`&quot;">​</a></h3><p>Runs the out-of-process liveness checker once by hand (normally it lives in cron). Exit codes: <code>0</code> healthy, <code>1</code> heartbeat stale/missing (alert sent), <code>2</code> the checker itself couldn&#39;t read the DB — which deliberately does <strong>not</strong> alert, so a broken checker can&#39;t page you about itself.</p><h2 id="dashboard-docs" tabindex="-1">Dashboard &amp; docs <a class="header-anchor" href="#dashboard-docs" aria-label="Permalink to &quot;Dashboard &amp; docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>npm run dash</code></td><td>Start the ops dashboard server (port 8787, needs <code>DASH_TOKEN</code>)</td></tr><tr><td><code>npm run dash:build</code></td><td>Build the React dashboard bundle (run once before first <code>dash</code>, or after UI updates)</td></tr><tr><td><code>npm run docs:dev</code></td><td>Local VitePress docs dev server</td></tr><tr><td><code>npm run docs:build</code></td><td>Build these docs into <code>docs/setup/</code></td></tr></tbody></table><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>npm run typecheck</code></td><td><code>tsc --noEmit</code> — the CI gate; the server only deploys typecheck-passing commits</td></tr><tr><td><code>npm test</code></td><td>Full vitest run with enforced coverage thresholds</td></tr><tr><td><code>npm run test:watch</code></td><td>Watch mode</td></tr></tbody></table><p class="cta-row"><a class="doc-btn ghost" href="./risk">Risk &amp; sizing</a><a class="doc-btn ghost" href="./advanced">Advanced setup</a><a class="doc-btn ghost" href="./dashboard">Dashboard</a><a class="doc-btn ghost" href="./faq">FAQ</a></p>',32)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
